-- =====================================================
-- SYNC Supabase -> Hetzner PostgreSQL
-- Änderungen seit 17.08.2026
-- =====================================================

-- Zuerst: DATEV Buchungen (63 Einträge)
-- Diese verwenden UPSERT um bestehende zu aktualisieren oder neue einzufügen

ON CONFLICT (id) DO UPDATE SET
  import_year = EXCLUDED.import_year,
  import_month = EXCLUDED.import_month,
  import_date = EXCLUDED.import_date,
  import_file_name = EXCLUDED.import_file_name,
  partita_iva = EXCLUDED.partita_iva,
  fornitore_name = EXCLUDED.fornitore_name,
  dokument_nr = EXCLUDED.dokument_nr,
  betrag = EXCLUDED.betrag,
  betrag_netto = EXCLUDED.betrag_netto,
  betrag_gesamt = EXCLUDED.betrag_gesamt,
  datum = EXCLUDED.datum,
  projekt_id = EXCLUDED.projekt_id,
  beschreibung = EXCLUDED.beschreibung,
  kategorie = EXCLUDED.kategorie,
  linked_invoice_id = EXCLUDED.linked_invoice_id,
  updated_at = EXCLUDED.updated_at,
  konto_nr = EXCLUDED.konto_nr,
  workflow_status = EXCLUDED.workflow_status,
  paid_at = EXCLUDED.paid_at,
  paid_by = EXCLUDED.paid_by,
  mwst_rate = EXCLUDED.mwst_rate,
  datum_registrazione = EXCLUDED.datum_registrazione,
  datum_documento = EXCLUDED.datum_documento,
  datum_competenza = EXCLUDED.datum_competenza,
  updated_by = EXCLUDED.updated_by;

-- =====================================================
-- INVOICES (27 Einträge)
-- =====================================================

ON CONFLICT (id) DO UPDATE SET
  file_path = EXCLUDED.file_path,
  file_name = EXCLUDED.file_name,
  partita_iva = EXCLUDED.partita_iva,
  invoice_number = EXCLUDED.invoice_number,
  status = EXCLUDED.status,
  linked_booking_id = EXCLUDED.linked_booking_id,
  workflow_status = EXCLUDED.workflow_status,
  updated_at = NOW();

-- Fertig!
SELECT 'Sync abgeschlossen: 63 DATEV Buchungen + 27 Invoices' as status;
